    // "A\B","C"
    line = "\"A\\B\",\"C\"";
    strings = TextFileInputUtils.convertLineToStrings(Mockito.mock(LogChannelInterface.class), line, inputMeta, ",", "\"", "\\");
    Assert.assertNotNull(strings);
    Assert.assertEquals("A\\B", strings[0]);
    Assert.assertEquals("C", strings[1]);
}

