    oraBulkLoaderMeta.setDataFile(tempDataVfsFilepath);
    oraBulkLoaderMeta.setControlFile(tempControlVfsFilepath);
    oraBulkLoaderMeta.setEraseFiles(true);
    oraBulkLoaderMeta.setLoadMethod("AUTO_END");
