    doReturn("1").when(transMeta).getVariable(Const.INTERNAL_VARIABLE_SLAVE_SERVER_NUMBER);
    doReturn("2").when(transMeta).getVariable(Const.INTERNAL_VARIABLE_CLUSTER_SIZE);
