    when(sysLogMessageSpy.getSyslog()).thenReturn(syslog);
    meta.setServerName("1");
    meta.setMessageFieldName("1");
    sysLogMessageSpy.init(meta, data);
    sysLogMessageSpy.dispose(meta, data);
}

