public void testLegacyLoadXml() throws IOException, HopXMLException {
    String legacyXml = IOUtils.toString(UnivariateStatsMetaTest.class.getClassLoader().getResourceAsStream("org/apache/hop/trans/steps/univariatestats/legacyUnivariateStatsMetaTest.xml"));
