    Answer<Object[]> answer = new Answer<Object[]>() {

        @Override
        public Object[] answer(InvocationOnMock invocation) throws Throwable {
            int i = index.getAndIncrement();
            return i < rows.size() ? rows.get(i) : null;
        }
    };
