    SQLStatement sqlStatement = clm.getSQLStatements(new TransMeta(), stepMeta, rowMetaInterface, repository, metaStore);
    String sql = sqlStatement.getSQL();
    Assert.assertTrue(StringUtils.countMatches(sql, schemaTable) == 3);
}

